#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32

__global__ void matmul_kernel_shared_mem(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col = bx * TILE_DIM + tx;

    float sum = 0.0f;

    for (int m = 0; m < (N + TILE_DIM - 1) / TILE_DIM; ++m) {
        if (row < N && (m * TILE_DIM + tx) < N) {
            sA[ty][tx] = A[row * N + m * TILE_DIM + tx];
        } else {
            sA[ty][tx] = 0.0f;
        }

        if ((m * TILE_DIM + ty) < N && col < N) {
            sB[ty][tx] = B[(m * TILE_DIM + ty) * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            sum += sA[ty][k] * sB[k][tx];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

