#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREAD_WORK 4 // Each thread computes a 4x4 tile of C

__global__ void matmul_kernel_reg_blocking(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int thread_id = ty * blockDim.x + tx;

    // Each thread loads THREAD_WORK elements from A and B
    int a_start_row = ty;
    int a_start_col = thread_id % (TILE_DIM / THREAD_WORK);

    int b_start_row = thread_id / (TILE_DIM / THREAD_WORK) ;
    int b_start_col = tx;


    float C_reg[THREAD_WORK][THREAD_WORK] = {0.0f};

    int num_tiles = (N + TILE_DIM - 1) / TILE_DIM;

    for (int t = 0; t < num_tiles; ++t) {
        // Load tiles into shared memory
        for(int i = 0; i < THREAD_WORK; ++i) {
            int row_a = by * TILE_DIM + a_start_row + i * (TILE_DIM/THREAD_WORK);
            int col_a = t * TILE_DIM + a_start_col;
             if(row_a < N && col_a < N){
                sA[a_start_row + i * (TILE_DIM/THREAD_WORK)][a_start_col] = A[row_a * N + col_a];
            } else {
                sA[a_start_row + i * (TILE_DIM/THREAD_WORK)][a_start_col] = 0.0;
            }

            int row_b = t * TILE_DIM + b_start_row;
            int col_b = bx * TILE_DIM + b_start_col + i * (TILE_DIM/THREAD_WORK);

            if(row_b < N && col_b < N){
                sB[b_start_row][b_start_col + i * (TILE_DIM/THREAD_WORK)] = B[row_b * N + col_b];
            } else {
                sB[b_start_row][b_start_col + i * (TILE_DIM/THREAD_WORK)] = 0.0;
            }
        }
        __syncthreads();

        // Compute from shared memory
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < THREAD_WORK; ++i) {
                for(int j = 0; j< THREAD_WORK; j++){
                    C_reg[i][j] += sA[ty*THREAD_WORK+i][k] * sB[k][tx*THREAD_WORK+j];
                }
            }
        }
        __syncthreads();
    }

    // Write results to global memory
    for (int i = 0; i < THREAD_WORK; i++) {
        for(int j = 0; j< THREAD_WORK; j++){
            int C_row = by * TILE_DIM + ty * THREAD_WORK + i;
            int C_col = bx * TILE_DIM + tx * THREAD_WORK + j;
            if(C_row < N && C_col < N){
                C[C_row * N + C_col] = C_reg[i][j];
            }
        }
    }
}


