#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREAD_WORK_ROWS 4
#define THREAD_WORK_COLS 4

__global__ void matmul_kernel_reg_blocking_fixed(const float* A, const float* B, float* C, int N) {
    __shared__ float sA[TILE_DIM][TILE_DIM];
    __shared__ float sB[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col = bx * TILE_DIM + tx;

    float C_reg[THREAD_WORK_ROWS][THREAD_WORK_COLS] = {0.0f};

    int num_tiles = (N + TILE_DIM - 1) / TILE_DIM;

    for (int t = 0; t < num_tiles; ++t) {
        // Load tiles into shared memory
        // Each thread loads a THREAD_WORK_ROWS x THREAD_WORK_COLS region of A and B
        for(int i=0; i < THREAD_WORK_ROWS; ++i) {
            int a_row = row + i * (TILE_DIM / THREAD_WORK_ROWS);
            int a_col = t * TILE_DIM + tx;
            if(a_row < N && a_col < N)
                sA[ty + i * (TILE_DIM / THREAD_WORK_ROWS)][tx] = A[a_row * N + a_col];
            else
                sA[ty + i * (TILE_DIM / THREAD_WORK_ROWS)][tx] = 0.0;
        }

        for(int i=0; i < THREAD_WORK_COLS; ++i) {
             int b_row = t * TILE_DIM + ty;
             int b_col = col + i * (TILE_DIM/THREAD_WORK_COLS);
             if(b_row < N && b_col < N)
                sB[ty][tx + i * (TILE_DIM/THREAD_WORK_COLS)] = B[b_row * N + b_col];
             else
                sB[ty][tx + i * (TILE_DIM/THREAD_WORK_COLS)] = 0.0;
        }

        __syncthreads();

        // Compute from shared memory
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < THREAD_WORK_ROWS; ++i) {
                for (int j = 0; j < THREAD_WORK_COLS; ++j) {
