                }
            }
        }
        __syncthreads();
    }

    // Write results to global memory
    for (int i = 0; i < THREAD_WORK_ROWS; i++) {
        for (int j = 0; j < THREAD_WORK_COLS; j++) {
            int C_row = row + i * (TILE_DIM / THREAD_WORK_ROWS);
